const revised = new Set([4, 6, 7, 8, 9, 10, 11, 12, 13, 15, 16, 17]);

const makeChecklist = (
  overrides: Partial<Record<number, { status: CourseQualityStatus; note?: string }>> = {},
): CourseQualityCheck[] => checklistItems.map((item, index) => {
  const number = index + 1;
  const defaultStatus: CourseQualityStatus = revised.has(number) ? "Revize Edildi" : "Uygun";
  return { item, status: overrides[number]?.status ?? defaultStatus, note: overrides[number]?.note };
});

